static inline float hf(uint16_t h){uint32_t s=h>>15,e=(h>>10)&31,f=h&1023;if(!e)return(s?-1.f:1.f)*std::ldexp(float(f),-24);if(e==31)return f?NAN:(s?-INFINITY:INFINITY);return(s?-1.f:1.f)*std::ldexp(1.f+float(f)/1024.f,int(e)-15);}
static inline uint16_t u16(const uint8_t*p){return uint16_t(p[0])|(uint16_t(p[1])<<8);}
static inline float elem(const GgufTensor&w,size_t i){const uint8_t*d=w.data;if(w.type==GgmlType::F32){float x;std::memcpy(&x,d+i*4,4);return x;}if(w.type==GgmlType::F16)return hf(u16(d+i*2));
size_t b=i/32,o=i%32; if(w.type==GgmlType::Q8_0){const uint8_t*q=d+b*34;return hf(u16(q))*float(int8_t(q[2+o]));}
if(w.type==GgmlType::Q4_0){const uint8_t*q=d+b*18;uint8_t z=q[2+o/2];return hf(u16(q))*float((o&1)?(z>>4):(z&15)-8);}
if(w.type==GgmlType::Q4_1){const uint8_t*q=d+b*20;uint8_t z=q[4+o/2];return hf(u16(q))*float((o&1)?(z>>4):(z&15))+hf(u16(q+2));}
if(w.type==GgmlType::Q5_0){const uint8_t*q=d+b*22;uint32_t qh;std::memcpy(&qh,q+2,4);uint8_t z=q[6+o/2];int v=(o&1)?z>>4:z&15;v|=((qh>>o)&1)<<4;return hf(u16(q))*float(v-16);}
if(w.type==GgmlType::Q5_1){const uint8_t*q=d+b*24;uint32_t qh;std::memcpy(&qh,q+4,4);uint8_t z=q[8+o/2];int v=(o&1)?z>>4:z&15;v|=((qh>>o)&1)<<4;return hf(u16(q))*float(v)+hf(u16(q+2));}
size_t sb=i/256,p=i%256,sub=p/128,pl=p%128,g=pl/32,e=pl%32;
if(w.type==GgmlType::Q2_K){const uint8_t*B=d+sb*84;uint8_t sc=B[sub*8+g];int q=(B[16+sub*32+e]>>(g*2))&3;return hf(u16(B+80))*float(sc&15)*q-hf(u16(B+82))*float(sc>>4);}
if(w.type==GgmlType::Q3_K){const uint8_t*B=d+sb*110;uint32_t s0,s1,s2;std::memcpy(&s0,B+96,4);std::memcpy(&s1,B+100,4);std::memcpy(&s2,B+104,4);uint32_t a[4]={(s0&0x0f0f0f0f)|((s2&0x03030303)<<4),(s1&0x0f0f0f0f)|(((s2>>2)&0x03030303)<<4),((s0>>4)&0x0f0f0f0f)|(((s2>>4)&0x03030303)<<4),((s1>>4)&0x0f0f0f0f)|(((s2>>6)&0x03030303)<<4)};int si=sub*8+g*2+(e>=16);int8_t sc=int8_t((a[si/4]>>(8*(si%4)))&255);int q=(B[32+sub*32+e]>>(g*2))&3;int sv=q-((B[e]&(1<<(sub*4+g)))?0:4);return hf(u16(B+108))*float(sc-32)*float(sv);}
if(w.type==GgmlType::Q4_K||w.type==GgmlType::Q5_K){const uint8_t*B=d+sb*(w.type==GgmlType::Q4_K?144:176);size_t grp=p/64,hal=(p%64)/32,ee=p%32,si=grp*2+hal;const uint8_t*sc=B+4;uint8_t scl=(si<4)?sc[si]&63:(sc[si+4]&15)|((sc[si-4]>>6)<<4);uint8_t sm=(si<4)?sc[si+4]&63:(sc[si+4]>>4)|((sc[si]>>6)<<4);int q=hal?(B[16+ee]>>4):(B[16+ee]&15);if(w.type==GgmlType::Q5_K&& (B[16+32+ee]&(1<<(grp*2+hal))))q+=16;return hf(u16(B))*float(scl*q)-hf(u16(B+2))*float(sm);}
if(w.type==GgmlType::Q6_K){const uint8_t*B=d+sb*210;size_t grp=(p%128)/32,local=p%32;int q=(grp&1)?B[32+local]>>4:B[local]&15;int h=(B[128+local]>>(grp*2))&3;int scidx=grp*2+local/16;return hf(u16(B+208))*float(int8_t(B[192+sub*8+scidx]))*float((q|(h<<4))-32);}
throw std::runtime_error("unsupported GGML tensor type");}

class Workers{std::vector<std::thread>w_;std::mutex m_;std::condition_variable cv_,done_;std::function<void(size_t)>fn_;size_t jobs_=0,active_=0,gen_=0;bool stop_=false;void worker(){size_t seen=0;for(;;){std::unique_lock<std::mutex>l(m_);cv_.wait(l,[&]{return stop_||gen_!=seen;});if(stop_)return;seen=gen_;auto f=fn_;size_t n=jobs_;l.unlock();for(;;){size_t i=next_.fetch_add(1,std::memory_order_relaxed);if(i>=n)break;f(i);}l.lock();if(--active_==0)done_.notify_one();}}std::atomic<size_t>next_{0};public:Workers(){unsigned n=std::thread::hardware_concurrency();if(!n)n=1;w_.reserve(n);for(unsigned i=0;i<n;i++)w_.emplace_back(&Workers::worker,this);}~Workers(){{std::lock_guard<std::mutex>l(m_);stop_=true;cv_.notify_all();}for(auto&t:w_)if(t.joinable())t.join();}void run(size_t n,const std::function<void(size_t)>&f){if(!n)return;if(n<w_.size()*2){for(size_t i=0;i<n;i++)f(i);return;}std::lock_guard<std::mutex>g(m_);jobs_=n;fn_=f;next_.store(0);active_=w_.size();++gen_;cv_.notify_all();std::unique_lock<std::mutex>l(m_);done_.wait(l,[&]{return active_==0;});}};
static Workers&workers(){static Workers x;return x;}
static inline float dot(const GgufTensor&w,const std::vector<float>&x,size_t base,size_t n,const CachePlan&cp,const std::atomic<bool>&stop){float s=0;size_t tk=cp.l1_tile_bytes?std::max<size_t>(4,cp.l1_tile_bytes/(sizeof(float)*2)):64;for(size_t j=0;j<n;j+=tk){if(stop.load(std::memory_order_relaxed))return 0;size_t len=std::min(tk,n-j);const uint8_t*wp=nullptr;if(w.type==GgmlType::F32)wp=w.data+(base+j)*4;else if(w.type==GgmlType::F16)wp=w.data+(base+j)*2;else wp=w.data+((base+j)/32)*(w.type==GgmlType::Q2_K?84:w.type==GgmlType::Q3_K?110:w.type==GgmlType::Q4_K?144:w.type==GgmlType::Q5_K?176:w.type==GgmlType::Q6_K?210:34);if(j+len<n)prefetch_range(wp,std::min<size_t>(len*(w.type==GgmlType::F32?4:2),cp.l2_window_bytes?cp.l2_window_bytes:len*2),cp.cache_line_bytes);for(size_t i=0;i<len;i++)s+=elem(w,base+j+i)*x[j+i];}return s;}
