void LlamaRuntime::load(const std::string&path){stop_requested_.store(false);cache_plan_=CachePlan::detect();model_.load(path);if(model_.str("general.architecture","")!="llama")throw std::runtime_error("unsupported architecture: expected llama");hidden_=model_.u64("llama.embedding_length");layers_=model_.u64("llama.block_count");heads_=model_.u64("llama.attention.head_count");kv_heads_=model_.u64("llama.attention.head_count_kv",heads_);ffn_=model_.u64("llama.feed_forward_length");ctx_=model_.u64("llama.context_length",2048);rope_dim_=model_.u64("llama.rope.dimension_count",hidden_/heads_);theta_=float(model_.f64("llama.rope.freq_base",10000));eps_=float(model_.f64("llama.attention.layer_norm_rms_epsilon",1e-5));if(!hidden_||!layers_||!heads_||!kv_heads_||hidden_%heads_||heads_%kv_heads_)throw std::runtime_error("invalid llama dimensions");head_dim_=hidden_/heads_;tokenizer_.load(model_);cache_.assign(layers_,{});size_t reserve=std::min<size_t>(ctx_,256)*kv_heads_*head_dim_;for(auto&c:cache_){c.k.reserve(reserve);c.v.reserve(reserve);}pos_=0;if(!model_.has_tensor("token_embd.weight")||!model_.has_tensor("output_norm.weight"))throw std::runtime_error("missing required tensors");}
std::vector<float>LlamaRuntime::embedding(uint32_t id)const{const auto&w=model_.tensor("token_embd.weight");if(w.shape.size()!=2||id>=w.shape[1]||w.shape[0]!=hidden_)throw std::runtime_error("invalid embedding tensor");std::vector<float>x(hidden_);for(size_t i=0;i<hidden_;i++)x[i]=w.value(id*hidden_+i);return x;}
std::vector<float>LlamaRuntime::matvec(const GgufTensor&w,const std::vector<float>&x,size_t out,size_t in)const{if(w.shape.size()!=2||w.shape[0]!=in||w.shape[1]!=out)throw std::runtime_error("unexpected weight shape: "+w.name);std::vector<float>y(out);workers().run(out,[&](size_t o){if(stop_requested_.load(std::memory_order_relaxed))return;y[o]=dot(w,x,o*in,in,cache_plan_,stop_requested_);});if(stop_requested_.load(std::memory_order_relaxed))throw std::runtime_error("generation stopped");return y;}
void LlamaRuntime::norm(std::vector<float>&x,const GgufTensor&w)const{if(w.elements()!=x.size())throw std::runtime_error("invalid norm tensor: "+w.name);float ss=0;for(float v:x)ss+=v*v;float inv=1/std::sqrt(ss/float(x.size())+eps_);workers().run(x.size(),[&](size_t i){if(!stop_requested_.load())x[i]*=inv*w.value(i);});if(stop_requested_.load())throw std::runtime_error("generation stopped");}
static void rope(std::vector<float>&x,size_t heads,size_t hd,size_t rd,size_t pos,float theta){rd=std::min(rd,hd);for(size_t h=0;h<heads;h++)for(size_t i=0;i<rd;i+=2){float inv=std::pow(theta,-float(i)/float(hd)),a=float(pos)*inv,c=std::cos(a),s=std::sin(a);size_t b=h*hd+i,u=x[b],v=x[b+1];x[b]=u*c-v*s;x[b+1]=u*s+v*c;}}
static float silu(float x){return x/(1.f+std::exp(-x));}
std::vector<float>LlamaRuntime::step(uint32_t token){if(pos_>=ctx_)throw std::runtime_error("context length exceeded");std::vector<float>x=embedding(token);for(size_t l=0;l<layers_;l++){if(stop_requested_.load())throw std::runtime_error("generation stopped");std::string p="blk."+std::to_string(l)+".";auto a=x;norm(a,model_.tensor(p+"attn_norm.weight"));auto q=matvec(model_.tensor(p+"attn_q.weight"),a,hidden_,hidden_);auto k=matvec(model_.tensor(p+"attn_k.weight"),a,kv_heads_*head_dim_,hidden_);auto v=matvec(model_.tensor(p+"attn_v.weight"),a,kv_heads_*head_dim_,hidden_);rope(q,heads_,head_dim_,rope_dim_,pos_,theta_);rope(k,kv_heads_,head_dim_,rope_dim_,pos_,theta_);auto&lc=cache_[l];size_t stride=kv_heads_*head_dim_;lc.k.insert(lc.k.end(),k.begin(),k.end());lc.v.insert(lc.v.end(),v.begin(),v.end());std::vector<float>attn(hidden_);size_t group=heads_/kv_heads_;workers().run(heads_,[&](size_t h){size_t kh=h/group;std::vector<float>scores(pos_+1);float mx=-std::numeric_limits<float>::infinity();for(size_t t=0;t<=pos_;t++){float s=0;for(size_t d=0;d<head_dim_;d++)s+=q[h*head_dim_+d]*lc.k[t*stride+kh*head_dim_+d];scores[t]=s/std::sqrt(float(head_dim_));mx=std::max(mx,scores[t]);}float den=0;for(float&s:scores){s=std::exp(s-mx);den+=s;}for(float&s:scores)s/=den;for(size_t d=0;d<head_dim_;d++){float z=0;for(size_t t=0;t<=pos_;t++)z+=scores[t]*lc.v[t*stride+kh*head_dim_+d];attn[h*head_dim_+d]=z;}});auto ao=matvec(model_.tensor(p+"attn_output.weight"),attn,hidden_,hidden_);workers().run(hidden_,[&](size_t i){x[i]+=ao[i];});auto f=x;norm(f,model_.tensor(p+"ffn_norm.weight"));auto gate=matvec(model_.tensor(p+"ffn_gate.weight"),f,ffn_,hidden_);auto up=matvec(model_.tensor(p+"ffn_up.weight"),f,ffn_,hidden_);workers().run(ffn_,[&](size_t i){if(!stop_requested_.load())gate[i]=silu(gate[i])*up[i];});auto down=matvec(model_.tensor(p+"ffn_down.weight"),gate,hidden_,ffn_);workers().run(hidden_,[&](size_t i){x[i]+=down[i];});}norm(x,model_.tensor("output_norm.weight"));const auto&out=model_.has_tensor("output.weight")?model_.tensor("output.weight"):model_.tensor("token_embd.weight");return matvec(out,x,tokenizer_.vocab_size(),hidden_);}
uint32_t LlamaRuntime::sample(const std::vector<float>&logits,const GenerationConfig&c,const std::vector<uint32_t>&history)const{std::vector<float>l=logits;if(c.repeat_penalty!=1.f)for(uint32_t id:history)if(id<l.size()){if(l[id]>0)l[id]/=c.repeat_penalty;else l[id]*=c.repeat_penalty;}if(c.temperature<=0)return uint32_t(std::max_element(l.begin(),l.end())-l.begin());size_t k=c.top_k?std::min(c.top_k,l.size()):l.size();std::vector<size_t>ix(l.size());std::iota(ix.begin(),ix.end(),0);if(k<ix.size()){std::nth_element(ix.begin(),ix.begin()+k,ix.end(),[&](size_t a,size_t b){return l[a]>l[b];});ix.resize(k);}float mx=-std::numeric_limits<float>::infinity();for(auto i:ix)mx=std::max(mx,l[i]);std::vector<double>p(k);double sum=0;for(size_t j=0;j<k;j++){p[j]=std::exp((l[ix[j]]-mx)/c.temperature);sum+=p[j];}if(c.top_p<1.f){std::vector<size_t>ord(k);std::iota(ord.begin(),ord.end(),0);std::sort(ord.begin(),ord.end(),[&](size_t a,size_t b){return p[a]>p[b];});double cut=0;size_t keep=k;for(size_t n=0;n<k;n++){cut+=p[ord[n]]/sum;if(cut>=c.top_p){keep=n+1;break;}}std::vector<size_t>ni;ni.reserve(keep);for(size_t n=0;n<keep;n++)ni.push_back(ix[ord[n]]);ix.swap(ni);p.resize(keep);sum=0;mx=-std::numeric_limits<float>::infinity();for(auto id:ix)mx=std::max(mx,l[id]);for(size_t j=0;j<ix.size();j++){p[j]=std::exp((l[ix[j]]-mx)/c.temperature);sum+=p[j];}k=ix.size();}static thread_local std::mt19937_64 rng(std::random_device{}());if(c.seed)rng.seed(c.seed);double r=std::uniform_real_distribution<double>(0,sum)(rng);for(size_t j=0;j<k;j++)if((r-=p[j])<=0)return uint32_t(ix[j]);return uint32_t(ix.back());}
std::vector<uint32_t>LlamaRuntime::generate_ids(const std::string&prompt,const GenerationConfig&c){return generate_ids(prompt,c,{});}std::vector<uint32_t>LlamaRuntime::generate_ids(const std::string&prompt,const GenerationConfig&c,const TokenCallback&cb){stop_requested_.store(false);pos_=0;for(auto&v:cache_){v.k.clear();v.v.clear();}auto ids=tokenizer_.encode(prompt);if(ids.empty())ids.push_back(tokenizer_.bos_id());std::vector<uint32_t>history=ids,out;out.reserve(c.max_tokens);std::vector<float>logits;for(uint32_t id:ids){if(stop_requested_.load()||pos_>=ctx_)break;logits=step(id);++pos_;}for(size_t n=0;n<c.max_tokens&&pos_<ctx_;n++){if(stop_requested_.load())break;uint32_t next=sample(logits,c,history);out.push_back(next);history.push_back(next);if(cb&&!cb(next))break;if(next==tokenizer_.eos_id())break;logits=step(next);++pos_;}return out;}
std::string LlamaRuntime::generate(const std::string&prompt,const GenerationConfig&c){std::string out;for(uint32_t id:generate_ids(prompt,c))out+=tokenizer_.decode(id);return out;}
